style:
.ury-hero-link {
    display: block;
    text-decoration: none;
    color: inherit;
}

.ury-hero-card {
    min-height: 88px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    border-radius: 8px;
    border: 1px solid var(--border-color);
    background: var(--card-bg);
}

.ury-hero-logo {
    height: 48px;
    border-radius: 6px;
}

.ury-hero-title {
    font-size: 16px;
    font-weight: 600;
}

.ury-hero-subtitle {
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 4px;
